import java.io.IOException; import java.nio.file.Path; import java.nio.file.Paths;
public class ListaDeClaseControlador {
 private final ListaDeClase modelo; private final ListaDeClaseVista vista; private final Path escritorio=Paths.get(System.getProperty("user.home"),"Desktop").toAbsolutePath().normalize();
 public ListaDeClaseControlador(ListaDeClase modelo,ListaDeClaseVista vista){this.modelo=modelo;this.vista=vista;}
 public void iniciar(){modelo.crearListaAleatoria(20);vista.mostrarMensaje("Se ha creado una lista inicial de 20 alumnos.");boolean seguir=true;while(seguir){vista.mostrarMenu();String op=vista.leerOpcion();switch(op.toLowerCase()){case "1":modelo.crearListaAleatoria(20);vista.mostrarMensaje("Lista regenerada con 20 alumnos y NIF no repetidos.");break;case "2":vista.mostrarAlumnos(modelo.getAlumnos());break;case "3":exportar(true);break;case "4":exportar(false);break;case "q":seguir=false;vista.mostrarMensaje("Programa finalizado.");break;default:vista.mostrarMensaje("Opción no válida.");}}}
 private void exportar(boolean personales){String tipo=personales?"de datos personales":"de direcciones";String nombre=vista.pedirNombreArchivo(tipo);if(nombre.isBlank()){vista.mostrarMensaje("No has indicado nombre de archivo.");return;}if(!nombre.toLowerCase().endsWith(".csv"))nombre+=".csv";Path destino=escritorio.resolve(nombre).normalize();if(!destino.getParent().equals(escritorio)){vista.mostrarMensaje("Escribe solo el nombre del archivo, sin carpetas.");return;}try{if(personales)modelo.exportarDatosPersonalesCSV(destino);else modelo.exportarDireccionesCSV(destino);vista.mostrarMensaje("Archivo creado correctamente en: "+destino);}catch(IOException e){vista.mostrarMensaje("No se pudo crear el archivo: "+e.getMessage());}}
}
